-- ============================================================
-- 20260829100000_review_grants_policies.sql
-- ============================================================
-- Code-review fixes: grants + policies the runtime needs but the original
-- migrations never provided. Found by security review 2026-08-29.

-- 1. Admin role management: user_roles had SELECT-only grant for authenticated,
--    so adminSetUserRole insert/delete always failed with permission denied.
GRANT INSERT, UPDATE, DELETE ON public.user_roles TO authenticated;

-- 2. computeStoreInsights: ai_insights had no INSERT grant and no INSERT
--    policy, so insights were silently never persisted. Store members may
--    insert insights for their own stores.
GRANT INSERT ON public.ai_insights TO authenticated;

DROP POLICY IF EXISTS "ai_insights_store_insert" ON public.ai_insights;
CREATE POLICY "ai_insights_store_insert" ON public.ai_insights
  FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.stores s
      WHERE s.id = store_id
        AND (s.owner_id = auth.uid() OR public.is_store_member(s.id, auth.uid()))
    )
  );

-- 3. Admin platform stats: orders/products had no admin SELECT policy, so the
--    admin overview only counted the admin's own rows. Read-only, admin-gated.
DROP POLICY IF EXISTS "orders_admin_read" ON public.orders;
CREATE POLICY "orders_admin_read" ON public.orders
  FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS "products_admin_read" ON public.products;
CREATE POLICY "products_admin_read" ON public.products
  FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS "stores_admin_read" ON public.stores;
CREATE POLICY "stores_admin_read" ON public.stores
  FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));


-- ============================================================
-- 20260829110000_conversations_unique.sql
-- ============================================================
-- Review fix: prevent duplicate conversations for the same product.
-- The Message-seller button had a double-click race (two inserts). The app
-- now guards in-UI, and this unique index is the DB-level backstop.
-- Dedupe first (keep the oldest thread), then enforce.

DELETE FROM public.conversations a
USING public.conversations b
WHERE a.buyer_id = b.buyer_id
  AND a.product_id IS NOT DISTINCT FROM b.product_id
  AND a.store_id = b.store_id
  AND a.created_at > b.created_at;

CREATE UNIQUE INDEX IF NOT EXISTS conversations_unique_buyer_product
  ON public.conversations (buyer_id, store_id, product_id)
  WHERE product_id IS NOT NULL;


-- ============================================================
-- 20260829120000_message_notifications.sql
-- ============================================================
-- Seller-replied notifications: writing a chat message inserts a
-- notification for the recipient. SECURITY DEFINER so the trigger can read
-- the conversation and write the notification regardless of RLS direction.

CREATE OR REPLACE FUNCTION public.notify_on_message()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_buyer uuid;
  v_seller uuid;
  v_recipient uuid;
  v_store_name text;
  v_title text;
BEGIN
  IF NEW.kind NOT IN ('text', 'image') THEN
    RETURN NEW;
  END IF;

  SELECT buyer_id, seller_id INTO v_buyer, v_seller
  FROM public.conversations WHERE id = NEW.conversation_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  v_recipient := CASE WHEN NEW.sender_id = v_buyer THEN v_seller ELSE v_buyer END;
  IF v_recipient IS NULL OR v_recipient = NEW.sender_id THEN RETURN NEW; END IF;

  SELECT s.name INTO v_store_name FROM public.stores s WHERE s.id = (
    SELECT store_id FROM public.conversations WHERE id = NEW.conversation_id
  );

  v_title := CASE
    WHEN NEW.sender_id = v_buyer THEN COALESCE(v_store_name, 'New message')
    ELSE 'New buyer message'
  END;

  INSERT INTO public.notifications (user_id, kind, title, body, payload)
  VALUES (
    v_recipient,
    'message',
    v_title,
    CASE WHEN NEW.kind = 'image' THEN '📷 Photo' ELSE left(COALESCE(NEW.body, ''), 120) END,
    jsonb_build_object('conversation_id', NEW.conversation_id)
  );
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_on_message ON public.messages;
CREATE TRIGGER trg_notify_on_message
  AFTER INSERT ON public.messages
  FOR EACH ROW EXECUTE FUNCTION public.notify_on_message();


-- ============================================================
-- 20260830120000_product_seller_terms.sql
-- ============================================================
-- Per-product seller terms:
--   delivery_available — does the seller offer delivery on this listing?
--   payment_type       — required when delivery is available:
--                        'on_delivery' | 'escrow' | 'before_delivery'
--   returns_note       — free text; blank falls back to platform default
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS delivery_available BOOLEAN,
  ADD COLUMN IF NOT EXISTS payment_type TEXT,
  ADD COLUMN IF NOT EXISTS returns_note TEXT;


-- ============================================================
-- 20260901120000_notifications_delete_policy.sql
-- ============================================================
-- Notifications: owners may delete their own rows. Powers the client-side
-- sweep that removes notifications a day after they were opened (read).
DROP POLICY IF EXISTS "notifications_own_delete" ON public.notifications;
CREATE POLICY "notifications_own_delete" ON public.notifications
  FOR DELETE TO authenticated
  USING (auth.uid() = user_id);


