-- ============================================================
-- 20260902110000_order_delivery_link.sql
-- ============================================================
-- ============================================================================
-- Order ↔ delivery system glue.
-- 1) When an order ships (status → 'shipped', home delivery), a
--    delivery_request is auto-opened so riders see it in their feed —
--    sellers no longer have to file it by hand.
-- 2) When the rider marks a delivery 'delivered', the order flips to
--    'delivered' and the buyer is notified (unlocking Confirm receipt).
-- Safe to re-run (drops/recreates its own triggers).
-- ============================================================================

-- ── 1. Shipping an order opens a rider request ─────────────────────────────
CREATE OR REPLACE FUNCTION public.open_delivery_on_ship() RETURNS trigger AS $$
DECLARE
  store_area text;
  buyer_area text;
BEGIN
  IF NEW.status = 'shipped'
     AND (NEW.fulfillment_type = 'delivery' OR NEW.fulfillment_type IS NULL)
     AND NOT EXISTS (
       SELECT 1 FROM public.delivery_requests dr
       WHERE dr.order_id = NEW.id AND dr.status <> 'cancelled'
     ) THEN

    SELECT NULLIF(trim(concat_ws(', ', s.area, s.city)), '') INTO store_area
    FROM public.stores s WHERE s.id = NEW.store_id;

    buyer_area := COALESCE(
      NEW.shipping_address->>'address',
      NEW.shipping_address->>'area',
      NEW.shipping_address->>'city',
      NULLIF(substring(NEW.notes FROM 'Delivery area: ([^·]+)'), ' ')
    );

    INSERT INTO public.delivery_requests (
      store_id, order_id, buyer_id, status, offered_fee,
      pickup_address, dropoff_address,
      notes
    ) VALUES (
      NEW.store_id, NEW.id, NEW.buyer_id, 'open', 15.00,
      COALESCE(store_area, 'Seller pickup point'),
      COALESCE(buyer_area, 'Buyer to confirm drop-off in chat'),
      concat_ws(' · ',
        CASE WHEN NEW.order_number IS NOT NULL THEN 'Order #' || NEW.order_number END,
        CASE WHEN NEW.payment_term = 'pay_on_delivery' THEN 'Collect payment on delivery (cash)' END,
        'Auto-created when the order shipped'
      )
    );
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS orders_open_delivery_ship ON public.orders;
CREATE TRIGGER orders_open_delivery_ship
  AFTER UPDATE OF status ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.open_delivery_on_ship();

-- ── 2. Rider marks delivered → order delivered + buyer notified ────────────
CREATE OR REPLACE FUNCTION public.sync_delivery_to_order() RETURNS trigger AS $$
DECLARE
  o record;
BEGIN
  IF NEW.status = 'delivered' AND OLD.status <> 'delivered' AND NEW.order_id IS NOT NULL THEN
    SELECT id, buyer_id, order_number INTO o FROM public.orders WHERE id = NEW.order_id;
    IF o.id IS NOT NULL THEN
      UPDATE public.orders SET status = 'delivered' WHERE id = o.id AND status <> 'delivered';
      INSERT INTO public.notifications (user_id, kind, title, body, payload)
      VALUES (
        o.buyer_id,
        'order',
        'Your order was delivered',
        'Order #' || o.order_number || ' has been dropped off. Confirm receipt to let the seller know it arrived.',
        jsonb_build_object('order_id', o.id, 'order_number', o.order_number)
      );
    END IF;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS delivery_sync_order_delivered ON public.delivery_requests;
CREATE TRIGGER delivery_sync_order_delivered
  AFTER UPDATE OF status ON public.delivery_requests
  FOR EACH ROW EXECUTE FUNCTION public.sync_delivery_to_order();


-- ============================================================
-- 20260902120000_seller_autopilot.sql
-- ============================================================
-- Seller AI auto-pilot: when ON, the store's AI answers buyers in chat by
-- itself — replies, takes orders (creates them), and alerts the seller.
-- Toggled per store from the seller chat thread header.
ALTER TABLE public.stores ADD COLUMN IF NOT EXISTS auto_pilot BOOLEAN NOT NULL DEFAULT false;


-- ============================================================
-- 20260902130000_inventory_auto_deduct.sql
-- ============================================================
-- ============================================================================
-- Live inventory: stock is a variable that moves with every purchase.
-- When an order item is recorded, the matching variant's inventory_qty is
-- decremented automatically (works for chat-tagged orders, AI-placed orders,
-- and any future checkout). The seller is notified when stock crosses the
-- low (≤3) and sold-out (0) thresholds — the AI copilot reports the rest.
-- Safe to re-run (drops/recreates its own trigger).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.deduct_stock_on_purchase() RETURNS trigger AS $$
DECLARE
  o record;
  v record;
  prod record;
  store_owner uuid;
  prev_qty int;
  new_qty int;
BEGIN
  IF NEW.quantity IS NULL OR NEW.quantity <= 0 THEN RETURN NEW; END IF;

  SELECT id, store_id INTO o FROM public.orders WHERE id = NEW.order_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- Locate the variant to decrement:
  IF NEW.variant_id IS NOT NULL THEN
    SELECT * INTO v FROM public.product_variants WHERE id = NEW.variant_id;
  ELSIF NEW.variant_title IS NOT NULL AND NEW.variant_title <> '' THEN
    SELECT pv.* INTO v
    FROM public.product_variants pv
    JOIN public.products p ON p.id = pv.product_id
    WHERE p.store_id = o.store_id
      AND lower(p.title) = lower(NEW.product_title)
      AND lower(pv.title) = lower(NEW.variant_title)
    LIMIT 1;
  END IF;

  IF v.id IS NULL THEN
    SELECT * INTO prod FROM public.products
    WHERE store_id = o.store_id AND lower(title) = lower(NEW.product_title)
    LIMIT 1;
    IF NOT FOUND THEN RETURN NEW; END IF;
    SELECT * INTO v FROM public.product_variants
    WHERE product_id = prod.id AND lower(title) = 'default'
    LIMIT 1;
    IF v.id IS NULL THEN
      SELECT * INTO v FROM public.product_variants
      WHERE product_id = prod.id
      ORDER BY position
      LIMIT 1;
    END IF;
  END IF;

  IF v.id IS NULL THEN RETURN NEW; END IF;
  SELECT title INTO prod FROM public.products WHERE id = v.product_id;
  SELECT owner_id INTO store_owner FROM public.stores WHERE id = o.store_id;

  prev_qty := COALESCE(v.inventory_qty, 0);
  new_qty := GREATEST(prev_qty - NEW.quantity, 0);
  UPDATE public.product_variants SET inventory_qty = new_qty WHERE id = v.id;

  -- Threshold alerts — only fire on the crossing, never repeatedly.
  IF new_qty = 0 AND prev_qty > 0 THEN
    INSERT INTO public.notifications (user_id, kind, title, body, payload)
    VALUES (store_owner, 'stock', 'Sold out',
            prod.title || ' is out of stock.',
            jsonb_build_object('product_id', v.product_id));
  ELSIF new_qty <= 3 AND prev_qty > 3 THEN
    INSERT INTO public.notifications (user_id, kind, title, body, payload)
    VALUES (store_owner, 'stock', 'Low stock',
            prod.title || ' has only ' || new_qty || ' left.',
            jsonb_build_object('product_id', v.product_id));
  END IF;

  RETURN NEW;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS order_items_deduct_stock ON public.order_items;
CREATE TRIGGER order_items_deduct_stock
  AFTER INSERT ON public.order_items
  FOR EACH ROW EXECUTE FUNCTION public.deduct_stock_on_purchase();


-- ============================================================
-- 20260902140000_store_kyc.sql
-- ============================================================
-- Seller KYC (Know Your Customer) verification.
-- kyc_verified: set by an ADMIN after checking the seller's government ID —
-- powers the gold "Verified" badge on the storefront.
-- kyc_submitted_at: when the seller last submitted ID documents (for the
-- upcoming in-app KYC submission flow).
ALTER TABLE public.stores
  ADD COLUMN IF NOT EXISTS kyc_verified BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS kyc_submitted_at TIMESTAMPTZ;

